import csv
targets = {
 "cooling_setpoint":"urn:buildgraph:tsref:44d6581d-51ed-5650-ad74-1bd56a16c03e",
 "heating_setpoint":"urn:buildgraph:tsref:3884ddd2-55e5-5e0a-9e6a-65822409bb01",
 "temp_sensor":"urn:buildgraph:tsref:75411709-a1c3-5621-904d-b03d146bc43d"
}
with open(CATALOG_CSV) as f:
    r=csv.DictReader(f)
    print("cols", r.fieldnames)
    for row in r:
        if row.get("point_uri") in targets.values():
            print(targets[[v for k,v in targets.items() if v==row["point_uri"]][0]], row)

import csv
cool="44d6581d-51ed-5650-ad74-1bd56a16c03e"
heat="3884ddd2-55e5-5e0a-9e6a-65822409bb01"
temp="75411709-a1c3-5621-904d-b03d146bc43d"
data={cool:{},heat:{},temp:{}}
with open(VALUES_CSV) as f:
    r=csv.DictReader(f)
    for row in r:
        ts=row["timeseries_id"]
        if ts in data:
            t=row["timestamp"]
            try: v=float(row["value"])
            except: v=None
            data[ts][t]=v
day="2018-01-27"
allts={t for d in data.values() for t in d if t.startswith(day)}
allts=sorted(allts)
print("num hours", len(allts))
ok=True
for t in allts:
    c=data[cool].get(t); h=data[heat].get(t); te=data[temp].get(t)
    if c is None or h is None or te is None:
        ok=False; print("missing", t, c,h,te); continue
    if not (h <= te <= c):
        ok=False; print("violation", t, "heat",h,"cool",c,"temp",te)
print("ALL OK", ok)
